<!doctype html><html lang="en" class="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= h($_SESSION['csrf_token']) ?>"><title>Book a Session · ThriveWell OS</title><link rel="stylesheet" href="/build/app.css"><script defer src="/build/app.js"></script></head>
<body><main class="booking-page"><section class="booking-hero card"><span class="eyebrow">Session booking</span><h1>Find support without pressure.</h1><p><?= h($booking['safety']['copy']) ?> <?= h($booking['safety']['ai_boundary']) ?></p><div class="booking-filters"><form method="get" action="/booking"><label>Focus area<input name="focus" placeholder="anxiety, stress, accessibility"></label><button type="submit">Filter gently</button></form></div><a class="link-inline" href="/logout">Logout</a></section>
<section class="card booking-list"><div class="card-head"><h2>Verified counsellors</h2><span><?= count($booking['counsellors']) ?> matches</span></div><div class="state-strip" aria-live="polite"><div class="success-state" hidden>Saved.</div><div class="error-state" hidden>Check details.</div></div><?php foreach ($booking['counsellors'] as $counsellor): ?><article class="booking-card"><img src="<?= h($counsellor['avatar']) ?>" alt=""><div><strong><?= h($counsellor['name']) ?></strong><span><?= h($counsellor['title']) ?> · <?= h($counsellor['specialties']) ?></span><small><?= h($counsellor['languages']) ?> · <?= h($counsellor['accessibility_tags']) ?> · ★ <?= h((string) $counsellor['rating']) ?></small><p><?= h($counsellor['bio']) ?></p><div class="match-reasons"><?php foreach ($counsellor['match_reasons'] as $reason): ?><em><?= h($reason) ?></em><?php endforeach; ?></div></div><div class="slot-grid"><?php foreach ($counsellor['availability'] as $slot): ?><form data-async-form action="/booking/hold" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="availability_id" value="<?= h((string) $slot['id']) ?>"><button type="submit"><strong><?= h(date('M j', strtotime($slot['starts_at']))) ?></strong><span><?= h(date('g:i A', strtotime($slot['starts_at']))) ?> · <?= money((int) $slot['fee_minor']) ?></span></button></form><?php endforeach; ?></div></article><?php endforeach; ?></section>
<section class="card booking-confirm"><div class="card-head"><h2>Confirm held session</h2><span>Payment-ready, not charged</span></div><form data-async-form action="/booking/confirm" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><label>Hold ID<input name="hold_id" placeholder="Returned after holding a slot" required></label><label>Timezone<input name="timezone" value="Africa/Lagos"></label><label>Session format<select name="session_format"><option value="video">Video</option><option value="audio">Audio</option><option value="chat">Chat</option></select></label><label>Support goal<input name="support_goal" placeholder="What would feel helpful today?"></label><button type="submit">Confirm session</button></form></section>
<section class="card booking-list"><div class="card-head"><h2>Your bookings</h2><span><?= count($bookings) ?> active</span></div><?php foreach ($bookings as $item): ?><article class="booking-row"><img src="<?= h($item['counsellor_avatar']) ?>" alt=""><div><strong><?= h($item['counsellor_name']) ?></strong><span><?= h(date('M j, g:i A', strtotime($item['starts_at']))) ?> · <?= h($item['timezone']) ?> · <?= money((int) $item['amount_minor']) ?></span></div><?= status_pill($item['status']) ?><form data-async-form action="/booking/cancel" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="session_booking_id" value="<?= h((string) $item['id']) ?>"><input type="hidden" name="reason" value="Client requested a pause."><button type="submit">Cancel calmly</button></form></article><?php endforeach; ?><?php if (!$bookings) empty_state('No bookings yet', 'Hold a time above, then confirm when you feel ready.'); ?></section></main></body></html>
